import{z as A,x as s,o,c as d,q as t,j as i,D as E,d as e,s as B,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"银行深化收束","description":"","frontmatter":{"title":"银行深化收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bm-map.md","filePath":"econ/bm-map.md","lastUpdated":1791413859000}'),m={name:"econ/bm-map.md"};function p(D,a,c,h,C,b){const n=s("Mermaid");return o(),d("div",null,[a[2]||(a[2]=t('<h1 id="银行深化收束" tabindex="-1">银行深化收束 <a class="header-anchor" href="#银行深化收束" aria-label="Permalink to &quot;银行深化收束&quot;">​</a></h1><div class="epigraph"><p>五课是同一条问题的五次换名：哪里有可跑的短债，哪里就需要删坏均衡的装置；装置跟不上负债的搬家，危机就发生在中间地带。</p><footer>—— 据 Diamond–Dybvig 1983、Gorton–Metrick 2012 整理</footer></div><p><a href="/econ/bm-international-banking">上一课</a>把弹性装置推到国境线上，本课程到此收束。五课连起来是一条单线：现代挤兑理论（<a href="/econ/bm-modern-runs">银行挤兑的现代理论</a>）把可跑的债收成有参数的协调博弈；监管资本（<a href="/econ/bm-regulatory-capital">监管资本的理论</a>）给安全网定价、给监督押金；影子银行（<a href="/econ/bm-shadow-deep">影子银行的深化</a>）把转换工序沿监管价格搬出表内，用无知的均衡造「安全」；最后贷款人（<a href="/econ/bm-lender-of-last-resort">最后贷款人</a>）以协调装置的形状把弹性沿负债分布重铺；国际银行（<a href="/econ/bm-international-banking">国际银行与跨境中介</a>）处理弹性出不了国境的最后一段。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>五课共有的失效模式只有一类：<strong>装置与负债的错位</strong>——用零售时代的贴现窗口接批发挤兑、用表内资本约束去管表外转换、用国内弹性去接美元链。与其配对的度量坑也只有一条：把「叫银行的机构」当系统性边界，而可跑的债从不理会牌照。所以收束课不写新机制，只把这条单线压成可操作的清单。</p><p><span class="marginnote">术语翻译：「可跑的债」（runnable debt）是持有人可随时要求兑现、且先到先得的负债——零售存款、回购、货币基金份额都算；只要它存在，挤兑协调博弈就存在，与机构挂不挂「银行」牌照无关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是给收束配一套可操作的定位协议：任何一段银行危机的叙述，先过三张清单——负债、装置、错位——把「可跑的债在哪、删坏均衡的装置在哪、两者落差在哪」逐项填出，再谈机制是哪一条。清单不产出参数，产出坐标：填不满的格子，就是这段叙述欠着的证据。</p><h3 id="三张清单" tabindex="-1">三张清单 <a class="header-anchor" href="#三张清单" aria-label="Permalink to &quot;三张清单&quot;">​</a></h3><p>把任何一段银行危机的叙述放上三张清单定位。<strong>负债清单</strong>：谁是可跑的债（可随时停止、先到先得或续命依赖、状态不可完全验证），量级多大、滚动日历在哪、分布在有保险还是无保险的持有者手里。<strong>装置清单</strong>：删坏均衡的候选——保险、暂停兑付、资本、最后贷款人承诺、互换线——各自的阈值效应与激励代价是什么，谁在哪个位置有权开窗。<strong>错位清单</strong>：负债在哪、装置在哪；表内与表外、境内与境外的落差就是危机的坐标。三张清单与<a href="/econ/cf-map">公司金融深化收束</a>的三张同构：先定位，再谈机制是哪一条。</p>',10)),(o(),i(l,null,{default:E(()=>[B(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E5%8F%AF%E8%B7%91%E7%9A%84%E5%80%BA%EF%BC%9A%E5%8D%8F%E8%B0%83%E5%8D%9A%E5%BC%88%22%5D%20--%3E%20NET%5B%22%E5%AE%89%E5%85%A8%E7%BD%91%EF%BC%9A%E5%88%A0%E5%9D%8F%E5%9D%87%E8%A1%A1%22%5D%0A%20%20NET%20--%3E%20CAP%5B%22%E8%B5%84%E6%9C%AC%EF%BC%9A%E7%BB%99%E5%AE%89%E5%85%A8%E7%BD%91%E5%AE%9A%E4%BB%B7%22%5D%20--%3E%20ARB%5B%22%E5%A5%97%E5%88%A9%EF%BC%9A%E5%B7%A5%E5%BA%8F%E5%A4%96%E7%A7%BB%E5%BD%B1%E5%AD%90%22%5D%0A%20%20ARB%20--%3E%20LOLR%5B%22LOLR%EF%BC%9A%E5%8D%8F%E8%B0%83%E8%A3%85%E7%BD%AE%22%5D%20--%3E%20INTL%5B%22%E8%B7%A8%E5%A2%83%EF%BC%9A%E4%BA%92%E6%8D%A2%E7%BA%BF%22%5D%0A%20%20INTL%20--%3E%20MIS%7B%22%E8%A3%85%E7%BD%AE%E4%B8%8E%E8%B4%9F%E5%80%BA%E9%94%99%E4%BD%8D%3F%22%7D%0A%20%20MIS%20--%3E%7C%22%E6%98%AF%22%7C%20CRISIS%5B%22%E5%8D%B1%E6%9C%BA%22%5D%0A%20%20MIS%20--%3E%7C%22%E5%90%A6%22%7C%20OK%5B%22%E7%A8%B3%E5%AE%9A%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("框架的生成力从文献骨架上看最清楚，五课共钉六根柱子：Diamond–Dybvig 1983 给可跑债的原型；Calomiris–Kahn 1991 与 Goldstein–Pauzner 2005 给纪律与唯一化；Holmström–Tirole 1997 给资本作为押金；Gorton–Metrick 2012 与 Dang 等 2017 给影子链的价格记法与设计论；Bagehot 1873 与 Rochet–Vives 2004 给弹性装置；McGuire–von Peter 2012 与 Cetorelli–Goldberg 2012 给跨境结构。未竟问题四件：其一，非银的系统性度量——2020 年 3 月的抢现与 2022 年的 LDI 说明可跑的债搬到市场端后，装置的资格清单还在追赶；其二，存款搬家的速度——"),r("a",{href:"/econ/mt-digital-currency-theory"},"数字货币的理论"),e("里的挤兑通道与第一课 SVB 的口径相连；其三，资本与流动性的联合定价，巴塞尔把两者并列，交互仍靠规则拼装；其四，国际最后贷款人的常设化与政治约束。")],-1)),(o(),i(l,null,{default:E(()=>[B(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20T1%5B%221873%EF%BC%9A%E9%9B%B6%E5%94%AE%E7%A5%A8%E6%8D%AE%E6%97%B6%E4%BB%A3%EF%BC%8CBagehot%20%E5%A4%84%E6%96%B9%22%5D%20--%3E%20T2%5B%221983%EF%BC%9A%E5%AD%98%E6%AC%BE%E4%BF%9D%E9%99%A9%E4%B8%8E%20DD%20%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20T2%20--%3E%20T3%5B%222008%EF%BC%9A%E6%89%B9%E5%8F%91%E5%9B%9E%E8%B4%AD%E6%8C%A4%E5%85%91%EF%BC%8C%E4%BE%BF%E5%88%A9%E5%BC%80%E5%88%B0%E9%9D%9E%E9%93%B6%22%5D%0A%20%20T3%20--%3E%20T4%5B%222020%EF%BC%9A%E5%B8%82%E5%9C%BA%E7%AB%AF%E6%8A%A2%E7%8E%B0%EF%BC%8C%E8%A3%85%E7%BD%AE%E8%BF%BD%E8%B4%9F%E5%80%BA%22%5D%0A%20%20T4%20--%3E%20T5%5B%222023%EF%BC%9A%E9%9D%A2%E5%80%BC%E5%8F%A3%E5%BE%84%E6%8A%B5%E6%8A%BC%E5%93%81%EF%BC%8C%E5%AD%98%E6%AC%BE%E5%A4%96%E9%80%83%E6%8F%90%E9%80%9F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">骨架横跨 1873–2017：装置理论先于危机形态一个多世纪，每次危机都把装置的适用清单往前推一格——读新文献，先找它拆的是哪根柱子的哪块假设。</span></p><p><span class="marginnote">数字实例：2023 年 SVB 的存款约九成不在 25 万美元保险上限之内，手机银行让挤兑在一天内走完零售时代数周的量——这就是「存款搬家的速度」与「装置资格清单还在追赶」的具体形状。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束不等于问题解决：本课程给的是坐标（负债、装置、错位），不是参数。理论侧留了缺口：协调阈值与宏观波动的一般均衡耦合——Gertler–Kiyotaki 一族只点名；银行间网络的传染只以<a href="/econ/bank-contagion">银行间传染</a>为界，没有展开。与主干分工也要交代：主干课钉模型与制度事实（<a href="/econ/why-intermediaries">why-intermediaries</a>、<a href="/econ/banking-crises-history">银行危机史</a>），本课程补理论化与装置的选址逻辑。下一课程「合同理论与机制设计」从银行的合同问题转向一般的合同与机制——银行是它的第一个应用场，不是终点。</p><p><span class="marginnote">常见误区：把收束课的三张清单当公式套。清单产出的是坐标而非参数——它告诉你缺口的方位（负债在哪、装置在哪），不预测缺口多深；深度要用具体模型的阈值与分布来算。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单线五步：可跑的债、安全网与资本的定价、工序外移、弹性沿负债重铺、弹性出关。</li><li>共同失效模式：装置与负债错位；牌照边界不是系统性边界。</li><li>三张清单：负债、装置、错位，用于定位任何银行危机的叙述。</li><li>文献骨架六根柱子，从 Diamond–Dybvig 1983 到 Cetorelli–Goldberg 2012。</li><li>出处口径：各课所引为准——Diamond–Dybvig 1983；Holmström–Tirole 1997；Gorton–Metrick 2012；Rochet–Vives 2004；McGuire–von Peter 2012；Cetorelli–Goldberg 2012。</li></ul>',7))])}const F=A(m,[["render",p]]);export{g as __pageData,F as default};
